/* gamepadxt.map - the linker version script for the shipped shared library.
 *
 * gamepadxt statically links SDL3. A statically linked dependency inherits
 * the library's public visibility unless the link says otherwise (the enetxt
 * lesson, release run 10, 2026-08-26: a vendored library's symbols leaked
 * from a dylib and could interpose on another extension's copy), and a
 * leaked SDL_* would interpose on any other SDL in the process. This script
 * keeps only gpx_*, which is all the .lcb binds by name; CMakeLists.txt gives
 * ld64 the same pattern.
 */
{
    global:
        gpx_*;
    local:
        *;
};
